if (md_input.momentum_nms == NULL || md_input.field_body_t == NULL) {
    md_state.mode = MD_FAULT;
    md_output.mode = MD_FAULT;
    md_output.elapsed = 0;
    md_output.saturation_mask = 0U;
    md_output.dipole_a_m2.x = 0.0;
    md_output.dipole_a_m2.y = 0.0;
    md_output.dipole_a_m2.z = 0.0;
    md_output.torque_nm.x = 0.0;
    md_output.torque_nm.y = 0.0;
    md_output.torque_nm.z = 0.0;
    md_output.dissipative_power = 0.0;
    return;
}

if (!adcs_is_finite_vec3(md_input.momentum_nms) || !adcs_is_finite_vec3(md_input.field_body_t)) {
    md_state.mode = MD_FAULT;
    md_output.mode = MD_FAULT;
    md_output.elapsed = 0;
    md_output.saturation_mask = 0U;
    md_output.dipole_a_m2.x = 0.0;
    md_output.dipole_a_m2.y = 0.0;
    md_output.dipole_a_m2.z = 0.0;
    md_output.torque_nm.x = 0.0;
    md_output.torque_nm.y = 0.0;
    md_output.torque_nm.z = 0.0;
    md_output.dissipative_power = 0.0;
    return;
}

// Validate configuration parameters
if (!isfinite(md_config.gain_s_inv) || md_config.gain_s_inv < 0.0 ||
    !isfinite(md_config.max_dipole_a_m2) || md_config.max_dipole_a_m2 < 0.0 ||
    !isfinite((double)md_config.extra_rest_per_saturated_cycle) || 
    md_config.extra_rest_per_saturated_cycle > 100U ||
    md_config.on_cycles < 1 || md_config.on_cycles > 100 ||
    md_config.rest_cycles < 1 || md_config.rest_cycles > 100) {
    md_state.mode = MD_FAULT;
    md_output.mode = MD_FAULT;
    md_output.elapsed = 0;
    md_output.saturation_mask = 0U;
    md_output.dipole_a_m2.x = 0.0;
    md_output.dipole_a_m2.y = 0.0;
    md_output.dipole_a_m2.z = 0.0;
    md_output.torque_nm.x = 0.0;
    md_output.torque_nm.y = 0.0;
    md_output.torque_nm.z = 0.0;
    md_output.dissipative_power = 0.0;
    return;
}

// Handle Disabled or Demand Absent condition
if (md_input.enable == 0 || md_input.demand == 0) {
    md_state.mode = MD_IDLE;
    md_state.elapsed = 0;
    md_state.saturated_on_cycles = 0;

    md_output.mode = MD_IDLE;
    md_output.elapsed = 0;
    md_output.saturation_mask = 0U;
    md_output.dipole_a_m2.x = 0.0;
    md_output.dipole_a_m2.y = 0.0;
    md_output.dipole_a_m2.z = 0.0;
    md_output.torque_nm.x = 0.0;
    md_output.torque_nm.y = 0.0;
    md_output.torque_nm.z = 0.0;
    md_output.dissipative_power = 0.0;
    return;
}

// State Machine Execution
switch (md_state.mode) {
    case MD_IDLE:
        // Demand begins in IDLE -> ON
        {
            adcs_actuator_command_t cmd;
            adcs_status_t st = adcs_momentum_unload_dipole(
                md_input.momentum_nms,
                md_input.field_body_t,
                md_config.gain_s_inv,
                md_config.max_dipole_a_m2,
                &cmd,
                &md_output.torque_nm
            );

            md_output.dipole_a_m2 = cmd.command;
            md_output.saturation_mask = cmd.saturated_axes;
            md_output.dissipative_power = 0.0;

            md_output.mode = MD_ON;
            md_output.elapsed = 1;

            md_state.mode = MD_ON;
            md_state.elapsed = 1;
            md_state.saturated_on_cycles = 0;
        }
        break;

    case MD_ON:
        {
            adcs_actuator_command_t cmd;
            adcs_status_t st = adcs_momentum_unload_dipole(
                md_input.momentum_nms,
                md_input.field_body_t,
                md_config.gain_s_inv,
                md_config.max_dipole_a_m2,
                &cmd,
                &md_output.torque_nm
            );

            md_output.dipole_a_m2 = cmd.command;
            md_output.saturation_mask = cmd.saturated_axes;
            md_output.dissipative_power = adcs_vec3_dot(&md_output.torque_nm, md_input.momentum_nms);

            md_state.elapsed++;
            md_output.elapsed = md_state.elapsed;

            if (cmd.saturated_axes != 0U) {
                md_state.saturated_on_cycles++;
            }

            if (md_state.elapsed >= md_config.on_cycles) {
                md_state.rest_target = md_config.rest_cycles + 
                                       md_state.saturated_on_cycles * md_config.extra_rest_per_saturated_cycle;

                md_state.mode = MD_REST;
                md_state.elapsed = 0;
                md_state.saturated_on_cycles = 0;

                md_output.mode = MD_REST;
                md_output.elapsed = 0;
                md_output.saturation_mask = 0U;
                md_output.dipole_a_m2.x = 0.0;
                md_output.dipole_a_m2.y = 0.0;
                md_output.dipole_a_m2.z = 0.0;
                md_output.torque_nm.x = 0.0;
                md_output.torque_nm.y = 0.0;
                md_output.torque_nm.z = 0.0;
                md_output.dissipative_power = 0.0;
            } else {
                md_output.mode = MD_ON;
            }
        }
        break;

    case MD_REST:
        {
            md_output.dipole_a_m2.x = 0.0;
            md_output.dipole_a_m2.y = 0.0;
            md_output.dipole_a_m2.z = 0.0;
            md_output.torque_nm.x = 0.0;
            md_output.torque_nm.y = 0.0;
            md_output.torque_nm.z = 0.0;
            md_output.dissipative_power = 0.0;
            md_output.saturation_mask = 0U;

            md_state.elapsed++;
            md_output.elapsed = md_state.elapsed;

            if (md_state.elapsed >= md_state.rest_target) {
                md_state.mode = MD_IDLE;
                md_state.elapsed = 0;

                md_output.mode = MD_IDLE;
                md_output.elapsed = 0;
            } else {
                md_output.mode = MD_REST;
            }
        }
        break;

    case MD_FAULT:
    default:
        md_output.mode = MD_FAULT;
        md_output.elapsed = 0;
        md_output.saturation_mask = 0U;
        md_output.dipole_a_m2.x = 0.0;
        md_output.dipole_a_m2.y = 0.0;
        md_output.dipole_a_m2.z = 0.0;
        md_output.torque_nm.x = 0.0;
        md_output.torque_nm.y = 0.0;
        md_output.torque_nm.z = 0.0;
        md_output.dissipative_power = 0.0;
        break;
}

