    // 1. Input Validation
    if ((md_input.momentum_nms == NULL) || (md_input.field_body_t == NULL)) {
        md_state.mode = MD_FAULT;
        goto output_fault;
    }
    if (!isfinite(md_config.gain_s_inv) || !isfinite(md_config.max_dipole_a_m2) ||
        md_config.gain_s_inv < 0.0 || md_config.max_dipole_a_m2 < 0.0 ||
        md_config.extra_rest_per_saturated_cycle > 100U) {
        md_state.mode = MD_FAULT;
        goto output_fault;
    }
    if (md_config.on_cycles < 1U || md_config.on_cycles > 100U ||
        md_config.rest_cycles < 1U || md_config.rest_cycles > 100U) {
        md_state.mode = MD_FAULT;
        goto output_fault;
    }
    if (!adcs_is_finite_vec3(md_input.momentum_nms) || !adcs_is_finite_vec3(md_input.field_body_t)) {
        md_state.mode = MD_FAULT;
        goto output_fault;
    }

    // 2. State Machine Execution
    switch (md_state.mode) {
        case MD_IDLE:
            if (!md_input.enable || !md_input.demand) {
                md_state.elapsed = 0;
                md_state.saturated_on_cycles = 0;
                md_state.mode = MD_IDLE;
            } else {
                md_state.mode = MD_ON;
                md_state.elapsed = 1;
                md_state.saturated_on_cycles = 0;
            }
            break;

        case MD_ON:
            if (!md_input.enable || !md_input.demand) {
                md_state.mode = MD_IDLE;
                md_state.elapsed = 0;
                md_state.saturated_on_cycles = 0;
            } else {
                adcs_status_t st = adcs_momentum_unload_dipole(
                    md_input.momentum_nms,
                    md_input.field_body_t,
                    md_config.gain_s_inv,
                    md_config.max_dipole_a_m2,
                    &md_output.dipole_a_m2,
                    &md_output.torque_nm
                );

                if (st != ADCS_OK) {
                    md_state.mode = MD_FAULT;
                    goto output_fault;
                }

